# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">GAZEL, KASİDE VE KOŞMA METİNLERİNİN KARŞILAŞTIRMALI DEĞERLENDİRMESİ (TDE2.4)</text>\n  <rect x="18" y="42" width="215" height="175" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="125" y="62" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">GAZEL (DİVAN ŞİİRİ)</text>\n  <text x="26" y="84" font-size="10" fill="#1e3a8a">• Temsilci: Fuzûlî (16. yy.)</text>\n  <text x="26" y="102" font-size="10" fill="#1e3a8a">• Nazım Birimi: Beyit (5-15 beyit)</text>\n  <text x="26" y="120" font-size="10" fill="#1e3a8a">• Ölçü: Aruz ölçüsü</text>\n  <text x="26" y="138" font-size="10" font-weight="bold" fill="#1d4ed8">• Uyak: aa / ba / ca / da / ea</text>\n  <text x="26" y="156" font-size="10" fill="#1e3a8a">• İlk beyit: Matla | Son beyit: Makta</text>\n  <text x="26" y="174" font-size="10" fill="#1e3a8a">• En güzel beyit: Beytü\'l-gazel</text>\n  <text x="26" y="192" font-size="10" fill="#1e3a8a">• Tema: Aşk, ayrılık, ıstırap (Lirik)</text>\n  <rect x="242" y="42" width="215" height="175" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="350" y="62" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#92400e">KASİDE (DİVAN ŞİİRİ)</text>\n  <text x="250" y="84" font-size="10" fill="#78350f">• Temsilci: Nedîm, Nef\'î (17-18. yy.)</text>\n  <text x="250" y="102" font-size="10" fill="#78350f">• Nazım Birimi: Beyit (33-99 beyit)</text>\n  <text x="250" y="120" font-size="10" fill="#78350f">• Ölçü: Aruz ölçüsü</text>\n  <text x="250" y="138" font-size="10" font-weight="bold" fill="#92400e">• Uyak: aa / ba / ca / da ...</text>\n  <text x="250" y="156" font-size="10" fill="#78350f">• Bölümler: Nesib, Girizgâh, Methiye,</text>\n  <text x="250" y="172" font-size="10" fill="#78350f">  Tegazzül, Fahriye, Dua</text>\n  <text x="250" y="192" font-size="10" fill="#78350f">• Tema: Din ve devlet büyüklerine övgü</text>\n  <rect x="466" y="42" width="216" height="175" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="574" y="62" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">KOŞMA (ÂŞIK TARZI HALK ŞİİRİ)</text>\n  <text x="474" y="84" font-size="10" fill="#14532d">• Temsilci: Karacaoğlan (17. yy.)</text>\n  <text x="474" y="102" font-size="10" fill="#14532d">• Nazım Birimi: Dörtlük (3-5 dörtlük)</text>\n  <text x="474" y="120" font-size="10" fill="#14532d">• Ölçü: 11\'li hece (6+5 veya 4+4+3)</text>\n  <text x="474" y="138" font-size="10" font-weight="bold" fill="#15803d">• Uyak: abab (xaxa) / cccb / dddb</text>\n  <text x="474" y="156" font-size="10" fill="#14532d">• Son dörtlükte: Tapşırma (Mahlas)</text>\n  <text x="474" y="174" font-size="10" fill="#14532d">• Çalgı: Bağlama / Saz eşliğinde</text>\n  <text x="474" y="192" font-size="10" fill="#14532d">• Tema: Doğa, aşk, gurbet, güzelleme</text>\n  <rect x="18" y="224" width="664" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Her üç nazım biçimi de Klasik Dönem Türk şiirinin ritim, ahenk ve estetik zenginliğini yansıtır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">BİLGİLENDİRİCİ METNİ EDEBÎ METNE (ŞİİRE) DÖNÜŞTÜRME SÜRECİ (TDE4.1)</text>\n  <rect x="20" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="180" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#9a3412">KAYNAK: BİLGİLENDİRİCİ (ÖĞRETİCİ) METİN</text>\n  <text x="32" y="88" font-size="10.5" fill="#7c2d12">• Amaç: Bilgi vermek, açıklamak, nesnel gerçekliği</text>\n  <text x="32" y="104" font-size="10.5" fill="#7c2d12">  doğrudan okuyucuya aktarmak (Ör. İstanbul yazısı).</text>\n  <text x="32" y="124" font-size="10.5" fill="#7c2d12">• Dilin İşlevi: Göndergesel (bilgi verici) işlev.</text>\n  <text x="32" y="144" font-size="10.5" fill="#7c2d12">• Kelime Anlamı: Gerçek ve terim anlamlı kelimeler;</text>\n  <text x="32" y="160" font-size="10.5" fill="#7c2d12">  tek anlamlılık ve doğrudan anlatım.</text>\n  <text x="32" y="180" font-size="10.5" font-weight="bold" fill="#9a3412">• Örnek: «İstanbul, Boğaziçi ve tarihi yarımadasıyla</text>\n  <text x="32" y="196" font-size="10.2" fill="#7c2d12">  Asya ile Avrupa\'yı birleştiren eşsiz bir kültür şehridir.»</text>\n  <rect x="360" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="520" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">HEDEF: EDEBÎ METİN (ŞİİR / NAZIM)</text>\n  <text x="372" y="88" font-size="10.5" fill="#581c87">• Amaç: Estetik zevk uyandırmak, sezdirmek, duygu ve</text>\n  <text x="372" y="104" font-size="10.5" fill="#581c87">  coşku kazandırmak (Ör. Nedîm\'in İstanbul Kasidesi).</text>\n  <text x="372" y="124" font-size="10.5" fill="#581c87">• Dilin İşlevi: Sanatsal (şiirsel / poetik) işlev.</text>\n  <text x="372" y="144" font-size="10.5" fill="#581c87">• Üslup Araçları: İmge, mecaz, söz sanatları (teşbih,</text>\n  <text x="372" y="160" font-size="10.5" fill="#581c87">  istiare, mübalağa), ölçü, uyak, redif, aliterasyon.</text>\n  <text x="372" y="180" font-size="10.5" font-weight="bold" fill="#6b21a8">• Örnek: «Bu şehr-i Sıtanbûl ki bî-misl ü bahâdır /</text>\n  <text x="372" y="196" font-size="10.2" fill="#581c87">  Bir sengine yekpâre Acem mülkü fedâdır.»</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Dönüştürme Adımları: 1) Ana fikri belirle → 2) İmge ve söz sanatları kur → 3) Ölçü, kafiye ve redifle dizelere dök.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">DİL BİLGİSİ: İSİM TAMLAMALARI VE ŞİİRDEKİ AHENK-ANLAM İŞLEVİ</text>\n  <rect x="20" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="180" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#065f46">İSİM TAMLAMASI TÜRLERİ (TAMLAYAN + TAMLANAN)</text>\n  <text x="32" y="88" font-size="10.5" font-weight="bold" fill="#064e3b">1. Belirtili İsim Tamlaması (Her ikisi de ek alır):</text>\n  <text x="40" y="104" font-size="10.2" fill="#064e3b">Tamlayan (-ın/-in/-un/-ün, -im) + Tamlanan (-ı/-i/-sı/-si)</text>\n  <text x="40" y="120" font-size="10.2" font-weight="bold" fill="#047857">Örnek: «kelimelerin ritmi», «suyun sesi», «gönlümün sultanı»</text>\n  <text x="32" y="140" font-size="10.5" font-weight="bold" fill="#064e3b">2. Belirtisiz İsim Tamlaması (Yalnız tamlanan ek alır):</text>\n  <text x="40" y="156" font-size="10.2" fill="#064e3b">Tamlayan (eksiz) + Tamlanan (-ı/-i/-sı/-si)</text>\n  <text x="40" y="172" font-size="10.2" font-weight="bold" fill="#047857">Örnek: «bahar mevsimi», «aşk derdi», «seher yeli»</text>\n  <text x="32" y="192" font-size="10.5" font-weight="bold" fill="#064e3b">3. Zincirleme İsim Tamlaması (En az üç isim):</text>\n  <text x="40" y="206" font-size="10.2" fill="#047857">Örnek: «divan şiirinin ahenk unsurları», «bahar dalının kokusu»</text>\n  <rect x="360" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="520" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">ŞİİRDE İSİM TAMLAMALARININ ESTETİK İŞLEVİ</text>\n  <text x="372" y="88" font-size="10.5" fill="#1e3a8a">• İmge Üretimi: Alışılmamış bağdaştırmalar ve teşbih-i</text>\n  <text x="372" y="104" font-size="10.5" fill="#1e3a8a">  beliğ (güzel benzetme) kurmayı sağlar:</text>\n  <text x="380" y="122" font-size="10.3" font-weight="bold" fill="#1d4ed8">«aşk odu (ateşi)», «gam yükü», «vuslat şarabı»</text>\n  <text x="372" y="142" font-size="10.5" fill="#1e3a8a">• Farsça Terkipler (Divan Şiirinde):</text>\n  <text x="380" y="158" font-size="10.2" fill="#1e3a8a">Tamlanan başta, tamlayan sonda yer alır:</text>\n  <text x="380" y="174" font-size="10.2" font-weight="bold" fill="#1d4ed8">«şehr-i Sıtanbûl» (İstanbul şehri), «derd-i aşk» (aşk derdi)</text>\n  <text x="372" y="194" font-size="10.5" fill="#1e3a8a">• Tamlayan ile tamlanan yer değiştirebilir (devrik dize).</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Belirtili isim tamlamasında tamlayan ile tamlanan arasına sıfat girebilir; tamlayan düşebilir!</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
